const APP_NAME="training emergencia prática CIC";
const APP_VERSION="5.0.0";
let deferredPrompt=null;
const $=s=>document.querySelector(s);
const main=$('#main');
let nav='home';
let session=null;
let trainingMode=localStorage.getItem('u39TrainingMode')||'study';

const MODE_INFO={
  study:{label:'Estudo guiado',desc:'Feedback imediato, dica técnica e rastreabilidade por etapa.'},
  assessment:{label:'Avaliação prática',desc:'Entrada direta, cenário oculto na execução, sem dicas e sem revelar acerto/erro até o debrief.'},
  instructor:{label:'Modo instrutor',desc:'Avaliação sem feedback imediato, com evento adicional/bifurcação e debrief técnico completo.'}
};
const SKILL_LABELS={seguranca:'Segurança',priorizacao:'Priorização',diagnostico:'Diagnóstico',processo:'Processo',coordenacao:'Coordenação'};
const defaultSkills=()=>({seguranca:50,priorizacao:50,diagnostico:50,processo:50,coordenacao:50});

function loadProgress(){
  try{return JSON.parse(localStorage.getItem('u39EmergencyProgressV5')||localStorage.getItem('u39EmergencyProgressV4')||localStorage.getItem('u39EmergencyProgressV3')||localStorage.getItem('u39EmergencyProgressV2')||'{"runs":[],"completed":{}}')}
  catch(e){return {runs:[],completed:{}}}
}
function saveProgress(p){localStorage.setItem('u39EmergencyProgressV5',JSON.stringify(p))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function clamp(v){return Math.max(0,Math.min(100,v))}
function clone(o){return JSON.parse(JSON.stringify(o))}
function isCorrect(st,opt){return st.selectUnsafe?opt[1]==='bad_as_target':opt[1]==='best'}
function bestOptionIndex(st){return st.options.findIndex(o=>st.selectUnsafe?o[1]==='bad_as_target':o[1]==='best')}

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('#installBtn').classList.remove('hidden')});
$('#installBtn').onclick=async()=>{if(!deferredPrompt)return;deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$('#installBtn').classList.add('hidden')};
if('serviceWorker' in navigator) window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
document.querySelectorAll('.bottom button').forEach(b=>b.onclick=()=>{nav=b.dataset.nav;session=null;setActive();render()});

function setActive(){document.querySelectorAll('.bottom button').forEach(b=>b.classList.toggle('active',b.dataset.nav===nav))}
function setMode(mode){trainingMode=mode;localStorage.setItem('u39TrainingMode',mode);render()}
window.setMode=setMode;

function scenarioCard(s){
  const p=loadProgress(), done=p.completed[s.id];
  const hasEvent=!!SIM_PROFILES[s.id]?.surprise;
  return `<article class="card">
    <div class="eyebrow">${esc(s.code)} · ${esc(s.level)}</div>
    <h3>${esc(s.title)}</h3><p>${esc(s.focus)}</p>
    <div class="meta">${s.view==='CIC'?'<span class="pill hot">PAINEL CIC</span>':''}<span class="pill">${s.stages.length} pontos de decisão</span><span class="pill">${esc(s.estimated)}</span>${hasEvent?'<span class="pill">ramificação</span>':''}${done?`<span class="pill hot">Melhor ${done}%</span>`:''}</div>
    <button class="primary go" onclick="startScenario('${s.id}')">${done?'Treinar novamente':'Iniciar cenário'}</button>
  </article>`
}
function modeSelector(){
  return `<div class="mode-selector">${Object.entries(MODE_INFO).map(([k,v])=>`<button class="${trainingMode===k?'active':''}" onclick="setMode('${k}')"><b>${esc(v.label)}</b><span>${esc(v.desc)}</span></button>`).join('')}</div>`
}
function home(){
  const p=loadProgress(),completed=Object.keys(p.completed).length,best=p.runs.length?Math.max(...p.runs.map(x=>x.score)):0;
  const cic=SCENARIOS.filter(s=>s.view==='CIC'), completos=SCENARIOS.filter(s=>s.view!=='CIC');
  main.innerHTML=`<section class="hero">
    <div class="eyebrow">Prática CIC · U-39 · Engine V5 · PROFUNDIDADE OPERACIONAL</div>
    <h1>Treinamento pensado a partir da cadeira do operador de painel.</h1>
    <p>Alarmes, PV/SP/MV, modo das malhas, tendências, priorização e coordenação CIC↔campo. A decisão modifica o estado do processo e pode mudar a rota do cenário.</p>
    <div class="warn"><b>Uso:</b> material de treinamento. Em situação real, prevalecem o procedimento controlado vigente, o SDCD, o Supervisor e os padrões de resposta a emergência.</div>
    <div class="kpis"><div class="kpi"><b>${SCENARIOS.length}</b><span>cenários totais</span></div><div class="kpi"><b>${SCENARIOS.reduce((n,s)=>n+s.stages.length,0)}</b><span>pontos de decisão</span></div><div class="kpi"><b>${cic.length}</b><span>simulações de painel</span></div><div class="kpi"><b>${completed}</b><span>cenários concluídos</span></div></div>
    <div class="section-title compact"><h2>Modo de treinamento</h2><span>${esc(MODE_INFO[trainingMode].label)}</span></div>${modeSelector()}
    <div class="modebox"><button class="ghost" onclick="startRandom()">⚡ Cenário surpresa com evento</button><button class="primary" onclick="startBlindAssessment()">🎯 Avaliação cega · ocorrência aleatória</button></div>
  </section>
  <div class="section-title"><h2>Simulações avançadas de Painel CIC</h2><span>${cic.length} cenários · prioridade desta versão</span></div><div class="grid">${cic.map(scenarioCard).join('')}</div>
  <div class="section-title"><h2>Procedimentos completos</h2><span>${completos.length} cenários-base</span></div><div class="grid">${completos.map(scenarioCard).join('')}</div>`
}
function missions(){
  const cic=SCENARIOS.filter(s=>s.view==='CIC'), completos=SCENARIOS.filter(s=>s.view!=='CIC');
  main.innerHTML=`<div class="section-title"><h2>Biblioteca de cenários</h2><span>${SCENARIOS.length} módulos</span></div>
  <p class="notice">A V5 mantém os mesmos 32 cenários e aprofunda a visão do Operador de Controle: mais decisões encadeadas, leitura de tendências, alarmes, modo das malhas, comandos no SDCD, barreiras, resposta da planta e confirmações de campo. Os cenários-base continuam disponíveis para reforço do procedimento.</p>
  ${modeSelector()}<div class="section-title compact"><h2>Painel CIC</h2><span>${cic.length}</span></div><div class="grid scenarios-grid">${cic.map(scenarioCard).join('')}</div><div class="section-title compact"><h2>Cenários-base</h2><span>${completos.length}</span></div><div class="grid scenarios-grid">${completos.map(scenarioCard).join('')}</div>`
}
function startRandom(){
  const pool=SCENARIOS.filter(s=>s.view==='CIC'); const candidates=pool.filter(s=>SIM_PROFILES[s.id]?.surprise).length?pool.filter(s=>SIM_PROFILES[s.id]?.surprise):pool;
  const s=candidates[Math.floor(Math.random()*candidates.length)];
  startScenario(s.id,{forceEvent:true,random:true})
}
function startBlindAssessment(){
  trainingMode='assessment'; localStorage.setItem('u39TrainingMode','assessment');
  const pool=SCENARIOS.filter(s=>s.view==='CIC'); const s=pool[Math.floor(Math.random()*pool.length)];
  startScenario(s.id,{random:true,blind:true})
}
window.startBlindAssessment=startBlindAssessment;
window.startScenario=function(id,opts={}){
  const s=SCENARIOS.find(x=>x.id===id), profile=SIM_PROFILES[id]||{initial:{},alerts:[],effects:[]};
  const forceEvent=!!opts.forceEvent;
  session={
    s,profile,index:-1,score:0,skills:defaultSkills(),answers:[],selected:null,
    state:clone(profile.initial||{}),timeline:(profile.alerts||[]).map((x,i)=>({seq:`E${i}`,text:x,kind:'initial'})),
    criticalErrors:[],orderCache:{},injectEvent:forceEvent||(trainingMode==='instructor'&&!!profile.surprise),
    eventHandled:false,pendingNext:null,branchLog:[],runTitle:s.title,random:!!opts.random,
    blind:!!opts.blind||trainingMode==='assessment'
  };
  if(trainingMode==='assessment'){session.index=0;renderQuestion()}else renderBrief()
}
function renderBrief(){
  const s=session.s,p=session.profile,event=p.surprise;
  main.innerHTML=`<div class="mission-head"><button class="back" onclick="session=null;render()">‹</button><div><div class="eyebrow">${esc(s.code)} · ${esc(s.level)} · ${esc(MODE_INFO[trainingMode].label)}</div><h1>${esc(s.title)}</h1><p>${esc(s.focus)} · ${esc(s.estimated)}</p></div></div>
  <section class="brief"><p>${esc(s.brief)}</p>
  <div class="signals">${s.signals.map(x=>`<div class="signal">◈ ${esc(x)}</div>`).join('')}</div>
  ${trainingMode==='instructor'&&event?`<div class="instructor-box"><b>Controle do instrutor</b><label><input type="checkbox" ${session.injectEvent?'checked':''} onchange="toggleInstructorEvent(this.checked)"> Injetar evento adicional/ramificação suportado pelo procedimento</label><small>${esc(event.title)}</small></div>`:''}
  <div class="sourcebox"><h3>Base do cenário</h3><ul>${s.sources.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>
  <button class="primary" style="width:100%;margin-top:12px" onclick="beginQuestions()">Entrar no cenário</button></section>`
}
window.toggleInstructorEvent=v=>{if(session)session.injectEvent=!!v}
window.beginQuestions=function(){session.index=0;renderQuestion()}

function statePanel(){
  const hiddenBlindKeys=new Set(['Estado','Rota','Cenário']);
  const entries=Object.entries(session.state).filter(([k])=>!(session.blind&&hiddenBlindKeys.has(k)));
  const active=session.timeline.filter(e=>e.kind!=='ok').slice(-4);
  return `<section class="sim-panel cic-console">
    <div class="sim-title"><div><span class="live-dot"></span><b>Visão CIC · SDCD</b></div><small>estado simulado · atualiza após cada decisão</small></div>
    <div class="cic-ribbon"><span><b>${active.length}</b> eventos/alarmes recentes</span><span>modo: <b>${esc(MODE_INFO[trainingMode].label)}</b></span><span>estação: <b>Operador de Controle</b></span></div>
    <div class="state-grid">${entries.map(([k,v])=>`<div class="state-item"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div>
    <div class="event-strip">${session.timeline.slice(-4).map(e=>`<div class="event ${e.kind||''}"><span>${esc(e.seq)}</span>${esc(e.text)}</div>`).join('')}</div>
  </section>`
}
function panelSnapshot(st){
  if(!st.panel?.length && !st.alarm)return '';
  const rows=(st.panel||[]).map(r=>`<div class="dcs-row"><b>${esc(r[0])}</b><span>${esc(r[1])}</span><small>${esc(r[2]||'')}</small><em>${esc(r[3]||'')}</em></div>`).join('');
  return `<section class="dcs-snapshot"><div class="dcs-head"><span>SIMULAÇÃO DE TELA · CIC</span>${st.alarm?`<b>⚠ ${esc(session.blind?'ALARMES ATIVOS · analisar causa x consequência':st.alarm)}</b>`:''}</div><div class="dcs-grid">${rows}</div><div class="dcs-foot">Leia primeiro a tendência e o modo da malha. Depois escolha a ação.</div></section>`
}
function meters(){
  if(trainingMode!=='study') return `<div class="assessment-lock">Desempenho oculto até o debrief · ${esc(MODE_INFO[trainingMode].label)}</div>`;
  const short={seguranca:'Seg.',priorizacao:'Prior.',diagnostico:'Diag.',processo:'Proc.',coordenacao:'Coord.'};
  return `<div class="enginebar">${Object.entries(session.skills).map(([k,v])=>`<div class="meter"><div class="mrow"><span>${short[k]}</span><b>${Math.round(v)}</b></div><div class="track"><div class="fill" style="width:${clamp(v)}%"></div></div></div>`).join('')}</div>`
}
function getOrder(stageIdx,st){
  if(session.orderCache[stageIdx])return session.orderCache[stageIdx];
  const a=st.options.map((_,i)=>i);
  {
    for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}
  }
  session.orderCache[stageIdx]=a; return a
}
function coordCallout(st){
  if(st.competency!=='coordenacao')return '';
  return `<div class="coord-callout"><b>CIC ↔ Campo / interfaces</b><span>Antes de escolher, verbalize: o que deve ser comunicado, executado e confirmado?</span></div>`
}
function renderQuestion(){
  const s=session.s,st=s.stages[session.index],pct=(session.index/s.stages.length)*100,order=getOrder(session.index,st);
  session.selected=null;
  const shownTitle=session.blind?'Ocorrência CIC · identificação retida':`${s.code} · ${s.title}`;
  const shownQ=session.blind&&st.blindQ?st.blindQ:st.q;
  main.innerHTML=`<div class="mission-head"><button class="back" onclick="confirmExit()">‹</button><div><div class="eyebrow">${esc(shownTitle)}</div><h1>Cenário em andamento</h1><p>Decisão ${session.index+1} de ${s.stages.length}${session.branchLog.length?' · rota ramificada':''}</p></div></div>
  <div class="progressline"><div style="width:${pct}%"></div></div>${statePanel()}${panelSnapshot(st)}${meters()}
  <section class="question"><div class="stage">Etapa ${session.index+1} · ${esc(SKILL_LABELS[st.competency]||st.competency)}${st.station?` · ${esc(st.station)}`:""}</div>
  <h2>${esc(shownQ)}</h2><div class="context">${esc(session.blind&&st.competency==='diagnostico'?'Interprete apenas as indicações disponíveis no painel e as confirmações solicitadas.':st.context)}</div>${coordCallout(st)}
  <div class="options">${order.map((orig,display)=>`<button class="option" data-orig="${orig}" onclick="choose(${orig})"><b>${String.fromCharCode(65+display)}.</b> ${esc(st.options[orig][0])}</button>`).join('')}</div>
  <div id="fb"></div><div class="qactions">${trainingMode==='study'?'<button class="ghost" onclick="showHint()">Entenda o foco</button>':'<span class="notice">Resposta sem feedback imediato.</span>'}<button id="next" class="primary hidden" onclick="nextStage()">${session.index===s.stages.length-1?'Ver debrief':'Próxima decisão'} →</button></div></section>`
}
window.showHint=function(){
  const st=session.s.stages[session.index];
  const map={seguranca:'Priorize barreiras, condição segura e proibições explícitas do procedimento.',priorizacao:'Procure a ação que reduz a ameaça dominante antes das ações de acabamento.',diagnostico:'Use tendências e confirmações que separem hipóteses e definam a rota.',processo:'Observe carga, pressão, vapor, temperatura, nível e inventário.',coordenacao:'Considere painel + campo + interfaces com outras unidades.'};
  $('#fb').innerHTML=`<div class="feedback">${esc(map[st.competency]||'Avalie sequência, variável crítica e consequência.')}</div>`
}
function applyOutcome(stageIdx,correct){
  const st=session.s.stages[stageIdx];
  const effect=session.profile.effects?.[stageIdx]?.[correct?'ok':'bad'] || st?.[correct?'stateOk':'stateBad'];
  if(effect?.updates)Object.assign(session.state,effect.updates);
  if(effect?.event){
    const seq=`E${session.timeline.length}`;
    session.timeline.push({seq,text:effect.event,kind:correct?'ok':'warn'});
    return effect.event
  }
  return correct?'Ação registrada.':'Decisão registrada com desvio em relação ao procedimento.'
}
window.choose=function(origIdx){
  if(session.selected!==null)return;
  const st=session.s.stages[session.index],opt=st.options[origIdx],correct=isCorrect(st,opt);
  session.selected=origIdx;
  const critical=!correct&&(st.criticalChoices||[]).includes(origIdx);
  session.skills[st.competency]=clamp(session.skills[st.competency]+(correct?10:(critical?-22:-12)));
  if(critical)session.skills.seguranca=clamp(session.skills.seguranca-12);
  if(correct)session.score+=1;
  const effectText=applyOutcome(session.index,correct);
  if(critical)session.criticalErrors.push({scenario:session.s.code,stage:session.index+1,text:opt[0],reference:st.reference||session.s.sources[0]});
  session.answers.push({
    scenario:session.s.code,title:session.s.title,stage:session.index+1,correct,critical,choice:opt[0],
    question:st.q,context:st.context,alarm:st.alarm||'',panel:clone(st.panel||[]),
    correctChoice:st.options[bestOptionIndex(st)][0],feedback:opt[2],reference:st.reference||session.s.sources[0],effect:effectText
  });
  const btn=document.querySelector(`.option[data-orig="${origIdx}"]`);
  if(trainingMode==='study')btn.classList.add('selected',correct?'correct':'wrong');else btn.classList.add('selected','neutral');
  if(trainingMode==='study'){
    let note=opt[2];
    if(!correct&&st.selectUnsafe){const target=st.options[bestOptionIndex(st)];note=`A alternativa crítica era: “${target[0]}” — ${target[2]}`}
    $('#fb').innerHTML=`<div class="feedback ${correct?'ok':'no'}"><b>${correct?'Decisão alinhada':'Reavaliar decisão'}.</b> ${esc(note)}<div class="process-effect"><b>Efeito no estado:</b> ${esc(effectText)}</div>${critical?'<div class="critical-flag">⚠ Barreira crítica violada nesta decisão.</div>':''}</div>`
  }else{
    $('#fb').innerHTML=`<div class="feedback sim-only"><b>Estado atualizado.</b> Continue a leitura das tendências, alarmes e permissivos antes da próxima decisão.</div>`
  }
  $('#next').classList.remove('hidden')
}
function shouldInjectEvent(){
  const sp=session.profile.surprise;
  return !!(session.injectEvent&&sp&&!session.eventHandled&&sp.afterStage===session.index)
}
window.nextStage=function(){
  if(session.selected===null)return;
  if(shouldInjectEvent()){
    session.pendingNext=session.index+1;
    renderInjectedEvent();
    return
  }
  if(session.index<session.s.stages.length-1){session.index++;renderQuestion()}else finishScenario()
}
function renderInjectedEvent(){
  const sp=session.profile.surprise;
  if(sp.updates)Object.assign(session.state,sp.updates);
  session.timeline.push({seq:`E${session.timeline.length}`,text:sp.title,kind:'surprise'});
  main.innerHTML=`<div class="mission-head"><button class="back" onclick="confirmExit()">‹</button><div><div class="eyebrow">Evento adicional · Training Scenario Engine</div><h1>${esc(sp.title)}</h1><p>O cenário mudou. Reavalie a rota antes de continuar.</p></div></div>${statePanel()}
  <section class="event-card"><div class="event-icon">⚡</div><h2>${esc(sp.title)}</h2><p>${esc(sp.body)}</p>
  <div class="sourcebox"><b>Rastreabilidade:</b> evento construído somente a partir da contingência descrita no procedimento do cenário.</div>
  <button class="primary" style="width:100%;margin-top:12px" onclick="continueInjectedEvent()">${sp.branchTo?'Aplicar bifurcação do procedimento':'Continuar com a nova condição'} →</button></section>`
}
window.continueInjectedEvent=function(){
  const sp=session.profile.surprise; session.eventHandled=true;
  if(sp.branchTo){
    const target=SCENARIOS.find(x=>x.id===sp.branchTo),profile=SIM_PROFILES[sp.branchTo];
    session.branchLog.push(`${session.s.code} → ${target.code}`);
    session.runTitle=`${session.s.title} → ${target.title}`;
    session.s=target;session.profile=profile;session.state={...session.state,...clone(profile.initial||{})};
    session.timeline.push({seq:`E${session.timeline.length}`,text:`Bifurcação aplicada: ${target.code} · ${target.title}`,kind:'branch'});
    session.index=0;session.orderCache={};session.injectEvent=false;renderQuestion();return
  }
  if(session.pendingNext<session.s.stages.length){session.index=session.pendingNext;renderQuestion()}else finishScenario()
}
window.confirmExit=function(){if(confirm('Sair deste cenário? O progresso desta rodada não será salvo.')){session=null;render()}}

function finishScenario(){
  const total=session.answers.length,score=total?Math.round(session.answers.filter(a=>a.correct).length/total*100):0;
  const p=loadProgress(),id=session.s.id;
  p.runs.push({id,title:session.runTitle,score,date:new Date().toISOString(),skills:session.skills,critical:session.criticalErrors.length,mode:trainingMode,branches:session.branchLog});
  p.runs=p.runs.slice(-80); p.completed[id]=Math.max(p.completed[id]||0,score); saveProgress(p); renderDebrief(score)
}
function renderDebrief(score){
  const weak=Object.entries(session.skills).sort((a,b)=>a[1]-b[1])[0],critical=session.criticalErrors.length;
  const headline=critical?'Barreira crítica violada — repetição necessária':score>=85?'Resposta consistente':score>=70?'Boa base, com pontos a consolidar':'Repetir o cenário é recomendado';
  const operationalStatus=critical?'REPETIR · houve violação de barreira crítica':score>=85?'CONSISTENTE · sem violação crítica':score>=70?'CONSOLIDAR · sem violação crítica':'REPETIR · aderência insuficiente';
  main.innerHTML=`<div class="debrief"><div class="eyebrow">Debrief operacional · ${esc(session.runTitle)}</div><div class="score">${score}%</div><h2>${headline}</h2>
  <p class="notice">A pontuação mede aderência ao treinamento e não representa certificação operacional. ${critical?`Foram registradas <b>${critical}</b> decisões com perda de barreira crítica.`:'Nenhuma barreira crítica foi violada nesta rodada.'}</p>
  <div class="validation-status ${critical?'status-critical':'status-ok'}"><b>Resultado do exercício:</b> ${esc(operationalStatus)}</div>
  <div class="bars">${Object.entries(session.skills).map(([k,v])=>`<div class="barrow"><span>${SKILL_LABELS[k]}</span><div class="bartrack"><div class="barfill" style="width:${v}%"></div></div><b>${Math.round(v)}</b></div>`).join('')}</div>
  ${session.branchLog.length?`<div class="takeaway"><b>Rota ramificada:</b> ${session.branchLog.map(esc).join(' · ')}</div>`:''}
  <div class="takeaway"><b>Foco para a próxima rodada:</b> ${SKILL_LABELS[weak[0]]}. Antes de agir, verbalize: “qual ameaça domina agora, qual barreira preciso confirmar e qual variável comprova a resposta?”.</div>
  <div class="section-title"><h2>Linha do tempo decisória</h2><span>o que viu → decisão → resposta da planta → referência</span></div>
  <div class="decision-review">${session.answers.map((a,i)=>`<article class="review-item ${a.correct?'ok':'no'} ${a.critical?'critical':''}">
    <div class="review-head"><b>T+${String(i).padStart(2,'0')} · ${esc(a.scenario)} · decisão ${a.stage}</b><span>${a.correct?'ALINHADA':a.critical?'CRÍTICA':'REVER'}</span></div>
    <p><b>Situação apresentada:</b> ${esc(a.question)}</p>
    ${a.alarm?`<p><b>Alarme/estado observado:</b> ${esc(a.alarm)}</p>`:''}
    <p><b>Sua decisão:</b> ${esc(a.choice)}</p>${!a.correct?`<p><b>Resposta de referência:</b> ${esc(a.correctChoice)}</p>`:''}
    <p><b>Resposta simulada da planta:</b> ${esc(a.effect)}</p><small>${esc(a.reference)}</small>
  </article>`).join('')}</div>
  <div class="section-title"><h2>Estado final do simulador</h2></div>${statePanel()}
  <div class="sourcebox"><h3>Fontes do módulo atual</h3><ul>${session.s.sources.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>
  <div class="qactions"><button class="ghost" onclick="session=null;nav='home';setActive();render()">Voltar</button><button class="primary" onclick="startScenario('${session.s.id}')">Refazer cenário</button></div></div>`
}

function reference(){
  const heads=STEAM.columns.map(x=>`<th>${esc(x)}</th>`).join('');
  const rows=STEAM.rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('');
  main.innerHTML=`<div class="section-title"><h2>Referência rápida</h2><span>consulta de estudo</span></div>
  <section class="sourcebox"><h3>Fundamento · V5 Profundidade Operacional CIC</h3><ul><li>PE.REF.OPE.CCF.089 — Ações Emergenciais na U-39 — Rev.02 — 26/06/2024.</li><li>Checklists M01 a M13 — campo/painel.</li><li>Anexo 1 — Tabela de Ajustes de Vapor para o Conversor.</li></ul><div class="validation-grid"><span><b>${SCENARIOS.length}</b> cenários preservados</span><span><b>${SCENARIOS.reduce((n,s)=>n+s.stages.length,0)}</b> decisões revisadas</span><span><b>${SCENARIOS.reduce((n,s)=>n+s.stages.filter(st=>!!st.reference).length,0)}</b> etapas rastreáveis</span><span><b>V5</b> profundidade operacional</span></div><p class="notice">Síntese para treinamento. Em manobra real, consultar a revisão controlada vigente.</p></section>
  <div class="section-title"><h2>Anexo 1 · Ajustes do Conversor</h2><span>20 linhas incorporadas do XLSX</span></div><div class="tablewrap"><table class="reftable"><thead><tr>${heads}</tr></thead><tbody>${rows}</tbody></table></div>
  <div class="section-title"><h2>Barreiras críticas</h2></div><div class="grid">
  <div class="card"><div class="eyebrow">Trip total</div><h3>L-3901 / L-3902</h3><p>Confirmar fechamento antes de inverter pressões entre regenerador e vaso separador.</p></div>
  <div class="card"><div class="eyebrow">Trip parcial</div><h3>ΔP L-3902</h3><p>Na recuperação de circulação, o item crítico cita diferencial adequado &gt;300 gf/cm².</p></div>
  <div class="card"><div class="eyebrow">Cat-Coolers</div><h3>TFD / intertravamento</h3><p>Cortar RV, reduzir carga para referência inicial de 7000 m³/d visando 700 °C e manter o intertravamento de alta temperatura ativo.</p></div>
  <div class="card"><div class="eyebrow">Flooding</div><h3>Não adicionar ar</h3><p>Não aumentar ar manualmente e não expor o campo. Reduzir gás gradativamente e acompanhar AI-39151.</p></div></div>`
}
function progress(){
  const p=loadProgress(),runs=[...p.runs].reverse();
  main.innerHTML=`<div class="section-title"><h2>Desempenho V5</h2><span>${p.runs.length} rodadas salvas neste aparelho</span></div>
  <div class="kpis"><div class="kpi"><b>${Object.keys(p.completed).length}</b><span>cenários concluídos</span></div><div class="kpi"><b>${p.runs.length?Math.round(p.runs.reduce((a,b)=>a+b.score,0)/p.runs.length):0}%</b><span>média</span></div><div class="kpi"><b>${p.runs.length?Math.max(...p.runs.map(r=>r.score)):0}%</b><span>melhor</span></div><div class="kpi"><b>${p.runs.reduce((a,b)=>a+(b.critical||0),0)}</b><span>barreiras críticas violadas</span></div></div>
  <div class="section-title"><h2>Histórico</h2></div><div class="history">${runs.length?runs.map(r=>`<div class="row"><div><b>${esc(r.title)}</b><br><small>${new Date(r.date).toLocaleString('pt-BR')} · ${esc(MODE_INFO[r.mode]?.label||r.mode||'modo anterior')}${r.branches?.length?' · '+esc(r.branches.join(' → ')):''}</small></div><div class="history-score"><strong>${r.score}%</strong>${r.critical?`<em>⚠ ${r.critical}</em>`:''}</div></div>`).join(''):'<div class="card"><p>Nenhuma rodada V5 concluída ainda.</p></div>'}</div>
  ${runs.length?'<button class="danger" style="margin-top:15px;width:100%" onclick="clearProgress()">Limpar desempenho V5 deste aparelho</button>':''}`
}
window.clearProgress=function(){if(confirm('Apagar o histórico V5 salvo neste aparelho?')){localStorage.removeItem('u39EmergencyProgressV5');render()}}
function render(){setActive();if(session){if(session.index<0)renderBrief();else renderQuestion();return}if(nav==='home')home();else if(nav==='missions')missions();else if(nav==='reference')reference();else progress()}
render();
